    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[][] intervals = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken(); intervals[i][0] = (long) in.nval;
            in.nextToken(); intervals[i][1] = (long) in.nval;
        }
        long[] newInterval = new long[2];
        in.nextToken(); newInterval[0] = (long) in.nval;
        in.nextToken(); newInterval[1] = (long) in.nval;
        long[][] result = insertInterval(intervals, newInterval);
        StringBuilder sb = new StringBuilder();
